def classes(word):
    # word: list of (letter, exponent); polygon vertices P_0..P_{n-1}, edge i runs P_i -> P_{i+1} counterclockwise
    n = len(word); parent = list(range(n))
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]; x = parent[x]
        return x
    def union(x, y): parent[find(x)] = find(y)
    ends = {}
    for i, (a, e) in enumerate(word):
        tail, head = (i, (i + 1) % n) if e == 1 else ((i + 1) % n, i)
        ends.setdefault(a, []).append((tail, head))
    for a, l in ends.items():
        assert len(l) == 2
        union(l[0][0], l[1][0]); union(l[0][1], l[1][1])
