# a Delta-simplex [p,q,r] has boundary [q,r] - [p,r] + [p,q]; edges named by (tail, head) -> (letter, sign)
def bd(tri, edge):
    p, q, r = tri
    out = {}
    for (u, v), s in [((q, r), 1), ((p, r), -1), ((p, q), 1)]:
        name, sign = edge[(u, v)]
        out[name] = out.get(name, 0) + s * sign
    return out
