for twist,expect in [(False,[(1,[]),(2,[]),(1,[])]),(True,[(1,[]),(1,[2]),(0,[])])]:
    tris=grid(twist)
    assert len({frozenset(t) for t in tris})==18 and all(len(set(t))==3 for t in tris)
    ec=Counter(frozenset(e) for t in tris for e in combinations(t,2))
    assert len(ec)==27 and set(ec.values())=={2}
    dims,mats,_=simplicial(tris)
    assert dims==[9,27,18]
    H=homology(dims,mats)
    assert H==expect,(twist,H)
# the Delta-complex data of the lesson (one vertex, edges a,b,c, triangles U,L)
assert homology([1,3,2],{1:[[0,0,0]],2:[[1,1],[1,1],[-1,-1]]})==[(1,[]),(2,[]),(1,[])]
assert homology([1,3,2],{1:[[0,0,0]],2:[[1,-1],[1,1],[-1,1]]})==[(1,[]),(1,[2]),(0,[])]
